"""The file adapter opens only the path returned by this download planner."""
from pathlib import PurePosixPath


def download_plan(principal, name):
    if not principal.get("authenticated"):
        raise PermissionError("Authentication required")
    tenant = principal.get("tenant_id")
    if tenant not in {"tenant-a", "tenant-b"}:
        raise PermissionError("Unknown tenant")
    if not isinstance(name, str) or not name or "\x00" in name:
        raise ValueError("Expected a relative export name")
    root = PurePosixPath("/srv/exports") / tenant
    target = root / PurePosixPath(name)
    return str(target)

